import XCTest

@MainActor final class PhonicsParityTests:XCTestCase {
    func testPhonicsMenuWrongRetryRepeatCollectAndRelaunch(){
        continueAfterFailure=false
        let app=XCUIApplication();app.launchEnvironment["PIYALI_OFFLINE_TESTS"]="1";app.launchEnvironment["PIYALI_TEST_IDENTITY_SCOPE"]=UUID().uuidString;app.launchEnvironment["PIYALI_ENTRY_INITIAL_LANGUAGE"]="en";app.launchEnvironment["PIYALI_ENTRY_INITIAL_THEME"]="light";app.launchEnvironment["PIYALI_PHONICS_FIXTURE"]="1";app.launchEnvironment["PIYALI_HEADLINE_FIXTURE"]="failure";app.launch();handleInitialPaperPencil(app)
        let name=app.textFields["entryName"];XCTAssertTrue(name.waitForExistence(timeout:15));name.tap();name.typeText("Phonics Learner");app.buttons["entryKeyboardDone"].tap();app.buttons["createAccount"].tap();handleInitialPaperPencil(app);XCTAssertTrue(app.buttons["startLearning"].waitForExistence(timeout:15));app.buttons["onboardingPractice"].tap();let spanish=app.buttons["onboardingOption-practice-es"];XCTAssertTrue(spanish.waitForExistence(timeout:5));spanish.tap();app.buttons["startLearning"].tap();XCTAssertTrue(app.buttons["productMenu"].waitForExistence(timeout:15))
        func phonics(){app.buttons["productMenu"].tap();app.buttons["productModeMenu"].tap();app.buttons["productMode-phonics"].tap();XCTAssertTrue(app.buttons["phonicsPrimary"].waitForExistence(timeout:20))}
        phonics();let primary=app.buttons["phonicsPrimary"];XCTAssertEqual(primary.label,"Practice");shot(app,"Native phonics menu front");primary.tap();XCTAssertTrue(app.staticTexts["phonicsWord"].waitForExistence(timeout:5));XCTAssertTrue(app.staticTexts["phonicsWord"].label.contains("casa"));shot(app,"Native phonics practice")
        primary.tap();XCTAssertTrue(app.otherElements["phonicsIncorrect"].waitForExistence(timeout:15));shot(app,"Native phonics wrong");primary.tap();XCTAssertEqual(primary.label,"Record");primary.tap();XCTAssertTrue(app.otherElements["phonicsCorrect"].waitForExistence(timeout:15));XCTAssertEqual(primary.label,"Next");shot(app,"Native phonics correct")
        app.buttons["phonicsBack"].tap();XCTAssertEqual(primary.label,"Next");app.buttons["phonicsPracticeAgain"].tap();primary.tap();XCTAssertTrue(app.otherElements["phonicsCorrect"].waitForExistence(timeout:15));primary.tap();XCTAssertTrue(app.otherElements["phonicsCard-authored-v1:es:Pre-A1:mesa"].waitForExistence(timeout:10));XCTAssertEqual(primary.label,"Practice");shot(app,"Native phonics collected first card")
        for _ in 0..<2 {app.terminate();app.launch();handleInitialPaperPencil(app);XCTAssertTrue(app.buttons["productMenu"].waitForExistence(timeout:15));phonics();XCTAssertTrue(app.otherElements["phonicsCard-authored-v1:es:Pre-A1:mesa"].waitForExistence(timeout:10));XCTAssertTrue(app.staticTexts["1 / 46"].exists);XCTAssertEqual(primary.label,"Practice")}
    }
    private func shot(_ app:XCUIApplication,_ name:String){let item=XCTAttachment(screenshot:app.screenshot());item.name=name;item.lifetime = .keepAlways;add(item)}
}
